import json
import re
from datetime import datetime
from collections import defaultdict

def parse_tutar(tutar_val):
    if isinstance(tutar_val, (int, float)):
        return float(tutar_val)

    if not isinstance(tutar_val, str):
        return None

    # Temizlik: ₺, TL ve boşluklar
    s = tutar_val.replace('₺', '').replace('TL', '').replace(' ', '').strip()
    if not s:
        return None

    # Nokta ve virgül kontrolü
    if ',' in s and '.' in s:
        # Hem virgül hem nokta varsa: . binlik, , ondalık
        s = s.replace('.', '').replace(',', '.')
    elif ',' in s:
        # Yalnız virgül varsa: ondalık
        s = s.replace(',', '.')
    elif '.' in s:
        # Yalnız nokta varsa: 
        # Eğer noktadan sonra tam 3 rakam varsa binlik ayırıcı (örn: 1.234)
        # Değilse ondalık (örn: 1.2)
        parts = s.split('.')
        if len(parts) == 2 and len(parts[1]) == 3:
            s = s.replace('.', '')
        else:
            pass # Zaten nokta ondalık

    try:
        return float(s)
    except ValueError:
        return None

def parse_tarih(tarih_val):
    if not isinstance(tarih_val, str):
        return None

    # Biçimler: YYYY-MM-DD, YYYY/MM/DD, GG.AA.YYYY
    formats = ['%Y-%m-%d', '%Y/%m/%d', '%d.%m.%Y']
    for fmt in formats:
        try:
            return datetime.strptime(tarih_val, fmt)
        except ValueError:
            continue

    # Türkçe tarih: G Ay YYYY (örn: 2 Nisan 2025)
    try:
        # Ay isimlerini Türkçe olarak tanımlayalım (basit bir mapping)
        aylar = {
            'ocak': 1, 'şubat': 2, 'mart': 3, 'nisan': 4, 'mayıs': 5, 'haziran': 6,
            'temmuz': 7, 'ağustos': 8, 'eylül': 9, 'ekim': 10, 'kasım': 11, 'aralık': 12
        }
        # Regex ile gün, ay_adı, yıl ayıklama
        match = re.match(r'(\d{1,2})\s+([a-zA-Z\u00C0-\u017F]+)\s+(\d{4})', tarih_val)
        if match:
            day = int(match.group(1))
            month_name = match.group(2).lower()
            year = int(match.group(3))

            # Türkçe karakter desteği için normalize etme (basitçe)
            month_name = month_name.replace('ı', 'i').replace('ğ', 'g').replace('ü', 'u').replace('ş', 's').replace('ö', 'o').replace('ç', 'c')
            # Ama daha güvenli yol:
            aylar_tr = {
                'ocak': 1, 'subat': 2, 'mart': 3, 'nisan': 4, 'mayis': 5, 'haziran': 6,
                'temmuz': 7, 'agustos': 8, 'eylul': 9, 'ekim': 10, 'kasim': 11, 'aralik': 12
            }

            # Tekrar normalize:
            m_norm = month_name
            if m_norm in aylar_tr:
                month = aylar_tr[m_norm]
                return datetime(year, month, day)
    except Exception:
        pass

    return None

